%add.1 = s32[1]{0} add(%x.1, %constant.1), metadata={op_name="jit(f_base)/add" source_file="third_party/py/jax/tests/python_callback_test.py" source_line=1352 source_end_line=1352 source_column=32 source_end_column=37}
